(text) => { const spans = []; const openers = /^\s*(great question|let me|i'll|sure[!,.]|certainly[!,.]|of course[!,.])/i; const closers = /(let me know if you need anything else|hope this helps)[^
]*$/i; const first = text.split('
').find(l => l.trim().length > 0) || ''; if (openers.test(first)) spans.push({ start: 0, end: first.length, why: 'preamble opener' }); const paras = text.trim().split(/
\s*
/); const last = paras[paras.length - 1] || ''; const cm = last.match(closers); if (cm) { const idx = text.lastIndexOf(last) + last.toLowerCase().lastIndexOf(cm[1].toLowerCase()); spans.push({ start: idx, end: idx + cm[1].length, why: 'closing pleasantry' }); } return { ok: spans.length === 0, detail: spans.length ? spans.length + ' preamble or closing pleasantry' : 'no preamble or closing pleasantry', spans }; }
